std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::collapse_edge(EdgeRef e) {
	//A2L3: Collapse Edge - general polygon version

	HalfedgeRef h = e->halfedge;
	HalfedgeRef t = h->twin;
	VertexRef keep = h->vertex;
	VertexRef remove = t->vertex;

	auto prev_in_face = [](HalfedgeRef he) {
		HalfedgeRef prev = he;
		while (prev->next != he) prev = prev->next;
		return prev;
	};

	struct Side_Info {
		HalfedgeRef halfedge;
		HalfedgeRef next;
		HalfedgeRef prev;
		FaceRef face;
		bool boundary = false;
		bool triangle = false;
		VertexRef opposite;
	};

	auto make_side = [&](HalfedgeRef he) {
		Side_Info side;
		side.halfedge = he;
		side.next = he->next;
		side.prev = prev_in_face(he);
		side.face = he->face;
		side.boundary = side.face->boundary;
		side.triangle = !side.boundary && side.next->next->next == he;
		side.opposite = side.prev->vertex;
		return side;
	};

	Side_Info hs = make_side(h);
	Side_Info ts = make_side(t);

	if ((hs.boundary && hs.face->degree() <= 3) || (ts.boundary && ts.face->degree() <= 3)) {
		return std::nullopt;
	}

	std::unordered_set<VertexRef> allowed_common;
	if (hs.triangle) allowed_common.emplace(hs.opposite);
	if (ts.triangle) allowed_common.emplace(ts.opposite);

	auto neighbors_without = [](VertexRef v, VertexRef skip) {
		std::unordered_set<VertexRef> neighbors;
		HalfedgeRef start = v->halfedge;
		HalfedgeRef he = start;
		do {
			VertexRef neighbor = he->twin->vertex;
			if (neighbor != skip) neighbors.emplace(neighbor);
			he = he->twin->next;
		} while (he != start);
		return neighbors;
	};

	std::unordered_set<VertexRef> keep_neighbors = neighbors_without(keep, remove);
	std::unordered_set<VertexRef> remove_neighbors = neighbors_without(remove, keep);
	for (VertexRef v : keep_neighbors) {
		if (remove_neighbors.count(v) && !allowed_common.count(v)) {
			return std::nullopt;
		}
	}

	auto surviving_triangle_edge_would_be_orphaned = [](Side_Info const& side) {
		if (!side.triangle) return false;
		return side.prev->twin->face->boundary && side.next->twin->face->boundary;
	};
	if (surviving_triangle_edge_would_be_orphaned(hs) || surviving_triangle_edge_would_be_orphaned(ts)) {
		return std::nullopt;
	}

	bool has_surviving_non_boundary_face = false;
	auto count_surviving_faces = [&](VertexRef v, FaceRef removed0, FaceRef removed1) {
		HalfedgeRef start = v->halfedge;
		HalfedgeRef he = start;
		do {
			FaceRef face = he->face;
			if (!face->boundary && face != removed0 && face != removed1) {
				has_surviving_non_boundary_face = true;
				return;
			}
			he = he->twin->next;
		} while (he != start);
	};
	count_surviving_faces(keep, hs.triangle ? hs.face : faces.end(), ts.triangle ? ts.face : faces.end());
	count_surviving_faces(remove, hs.triangle ? hs.face : faces.end(), ts.triangle ? ts.face : faces.end());
	if (!has_surviving_non_boundary_face) return std::nullopt;

	std::vector<HalfedgeRef> remove_outgoing;
	{
		HalfedgeRef start = remove->halfedge;
		HalfedgeRef he = start;
		do {
			remove_outgoing.emplace_back(he);
			he = he->twin->next;
		} while (he != start);
	}

	for (HalfedgeRef he : remove_outgoing) {
		if (he == t) continue;
		if (hs.triangle && he == hs.next) continue;
		he->vertex = keep;
	}

	HalfedgeRef keep_halfedge = halfedges.end();
	auto choose_halfedge = [&](HalfedgeRef candidate) {
		if (keep_halfedge == halfedges.end()) keep_halfedge = candidate;
	};

	if (!hs.triangle) choose_halfedge(hs.next);
	else choose_halfedge(hs.prev->twin);
	if (!ts.triangle) choose_halfedge(ts.next);
	else choose_halfedge(ts.prev->twin);

	auto collapse_surviving_face = [&](Side_Info const& side) {
		side.prev->next = side.next;
		side.face->halfedge = side.next;
	};

	auto collapse_triangle_face = [&](Side_Info const& side) {
		HalfedgeRef from_keep = side.prev->twin;
		HalfedgeRef from_opp = side.next->twin;
		EdgeRef keep_edge = side.prev->edge;
		EdgeRef remove_edge = side.next->edge;
		VertexRef opposite = side.opposite;

		keep_edge->sharp = keep_edge->sharp || remove_edge->sharp;
		keep_edge->halfedge = from_keep;
		from_keep->twin = from_opp;
		from_opp->twin = from_keep;
		from_keep->edge = keep_edge;
		from_opp->edge = keep_edge;

		if (opposite->halfedge == side.prev) {
			opposite->halfedge = from_opp;
		}

		erase_halfedge(side.prev);
		erase_halfedge(side.next);
		erase_face(side.face);
		erase_edge(remove_edge);
	};

	if (hs.triangle) collapse_triangle_face(hs);
	else collapse_surviving_face(hs);
	if (ts.triangle) collapse_triangle_face(ts);
	else collapse_surviving_face(ts);

	if (keep_halfedge == halfedges.end()) return std::nullopt;

	keep->position = 0.5f * (keep->position + remove->position);
	interpolate_data(std::vector<VertexCRef>{keep, remove}, keep);
	keep->halfedge = keep_halfedge;

	erase_halfedge(h);
	erase_halfedge(t);
	erase_edge(e);
	erase_vertex(remove);

	return keep;
}

