/*
 * bisect_edge: split an edge without splitting the adjacent faces
 *  e: edge to split
 *
 * returns: added vertex
 *
 * We provide this as an example for how to implement local operations.
 * (and as a useful subroutine!)
 */
std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::bisect_edge(EdgeRef e) {
	HalfedgeRef h = e->halfedge;
	HalfedgeRef t = h->twin;
	HalfedgeRef h_next = h->next;
	HalfedgeRef t_next = t->next;

	VertexRef a = h->vertex;
	VertexRef b = t->vertex;

	VertexRef vm = emplace_vertex();
	vm->position = 0.5f * (a->position + b->position);
	interpolate_data({VertexCRef(a), VertexCRef(b)}, vm);

	EdgeRef e2 = emplace_edge(e->sharp);
	HalfedgeRef h2 = emplace_halfedge();
	HalfedgeRef t2 = emplace_halfedge();

	h2->set_tnvef(t, h_next, vm, e2, h->face);
	t2->set_tnvef(h, t_next, vm, e, t->face);

	h->twin = t2;
	h->next = h2;

	t->twin = h2;
	t->next = t2;
	t->edge = e2;

	e->halfedge = h;
	e2->halfedge = h2;
	vm->halfedge = t2;

	interpolate_data({HalfedgeCRef(h), HalfedgeCRef(h_next)}, h2);
	interpolate_data({HalfedgeCRef(t), HalfedgeCRef(t_next)}, t2);

	return vm;
}


/*
 * split_edge: split an edge and adjacent (non-boundary) faces
 *  e: edge to split
 *
 * returns: added vertex. vertex->halfedge should lie along e
 *
 * Note that when splitting the adjacent faces, the new edge
 * should connect to the vertex ccw from the ccw-most end of e
 * within the face.
 *
 * Do not split adjacent boundary faces.
 */
std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::split_edge(EdgeRef e) {
	// A2L2 (REQUIRED): split_edge

	auto vm_opt = bisect_edge(e);
	if (!vm_opt) return std::nullopt;

	VertexRef vm = *vm_opt;
	HalfedgeRef h = e->halfedge;
	HalfedgeRef h2 = h->next;
	HalfedgeRef t = h2->twin;

	auto split_non_boundary_side = [&](HalfedgeRef before) {
		FaceRef face = before->face;
		if (face->boundary) return;

		HalfedgeRef after = before->next;
		HalfedgeRef across = after->next;
		HalfedgeRef rest = across->next;

		FaceRef new_face = emplace_face(false);
		EdgeRef new_edge = emplace_edge(false);
		HalfedgeRef to_old = emplace_halfedge();
		HalfedgeRef to_new = emplace_halfedge();

		// Keep `before` on the original face and peel a triangle from the ccw-most end.
		interpolate_data({HalfedgeCRef(before), HalfedgeCRef(after)}, to_old);
		interpolate_data({HalfedgeCRef(across), HalfedgeCRef(rest)}, to_new);

		if (face->halfedge == after || face->halfedge == across) {
			face->halfedge = before;
		}

		new_face->halfedge = after;
		new_edge->halfedge = to_old;

		to_old->set_tnvef(to_new, rest, vm, new_edge, face);
		to_new->set_tnvef(to_old, after, rest->vertex, new_edge, new_face);

		before->next = to_old;
		across->next = to_new;
		after->face = new_face;
